/* syr2k.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"

/* Tunable blocking factor for the j-loop.
 * Can be adjusted for a particular cache hierarchy. */
#ifndef SYR2K_J_BLOCK
# define SYR2K_J_BLOCK 32
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
      B[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i*j+3)%n) / m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations compared to the baseline PolyBench version:
   - Use restrict-qualified local pointers to give the compiler
     stronger aliasing information for A, B, and C.
   - Reorder the inner loops so that the innermost loop runs over
     the k dimension (columns), giving contiguous access to rows of
     A and B and improving data locality and vectorization.
   - Accumulate the rank-2k contributions to C[i][j] in a register
     and write C[i][j] back only once, instead of updating it inside
     the innermost k loop. This significantly reduces memory traffic
     to the C matrix.
   - Apply optional j-loop blocking (tuned via SYR2K_J_BLOCK) to keep
     the active part of row i of C, and the corresponding rows of A/B,
     hot in the cache.
   - Provide an optional OpenMP parallel-for pragma on the outer i-loop
     to exploit multiple cores if compiled with -fopenmp. Without OpenMP,
     the pragma is safely ignored by the compiler.

   Algebraically, the kernel still computes, for the lower triangular
   part of C:
     C <- beta * C + alpha * (A * B^T + B * A^T)
   with A and B of size N x M and C of size N x N.
*/
static void __attribute__((flatten, noinline))
kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* PolyBench loop bounds (may differ from raw n/m if the framework
   * selects a different runtime size, but are always <= n, m). */
  const int nn = _PB_N;
  const int mm = _PB_M;

  /* Create local restrict-qualified views of the 2D arrays.
   * This tells the compiler that A, B, and C do not alias, which
   * is crucial for aggressive vectorization and reordering. */
  DATA_TYPE (*restrict C_)[n]       = (DATA_TYPE (*restrict)[n])C;
  const DATA_TYPE (*restrict A_)[m] = (const DATA_TYPE (*restrict)[m])A;
  const DATA_TYPE (*restrict B_)[m] = (const DATA_TYPE (*restrict)[m])B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

#pragma scop
  /* Parallelize across rows of C when OpenMP is enabled.
   * Each iteration of the i-loop updates a distinct row of C
   * and is therefore independent. */
#pragma omp parallel for schedule(static) private(j,k)
  for (i = 0; i < nn; ++i)
  {
    DATA_TYPE *restrict       Ci = C_[i];
    const DATA_TYPE *restrict Ai = A_[i];
    const DATA_TYPE *restrict Bi = B_[i];

    /* Block the j-loop. Each block operates on a contiguous segment
     * of row i of C (Ci[j..j_end)) and the corresponding rows j of A/B.
     * This helps the cache when nn is large by limiting the active
     * working set. */
    for (int jb = 0; jb <= i; jb += SYR2K_J_BLOCK)
    {
      int j_end = i + 1;
      if (j_end > jb + SYR2K_J_BLOCK)
        j_end = jb + SYR2K_J_BLOCK;

      for (j = jb; j < j_end; ++j)
      {
        const DATA_TYPE *restrict Aj = A_[j];
        const DATA_TYPE *restrict Bj = B_[j];

        /* Accumulate the entire contribution of the k-dimension
         * to C[i][j] in a scalar register. The innermost loop runs
         * over k, which traverses rows of A and B contiguously
         * (Aj[k], Bj[k], Ai[k], Bi[k]), improving locality and
         * enabling vectorization. */
        DATA_TYPE sum = (DATA_TYPE)0;
        for (k = 0; k < mm; ++k)
        {
          /* Fused form of the two dot-products:
           *   sum_1 += A[j][k] * B[i][k];
           *   sum_2 += B[j][k] * A[i][k];
           *   sum   = sum_1 + sum_2;
           */
          sum += Aj[k] * Bi[k] + Bj[k] * Ai[k];
        }

        /* Finish the update of C[i][j] entirely in registers:
         *   C[i][j] = beta * C[i][j] + alpha * sum;
         * This replaces the original pattern where C[i][j] was
         * loaded and stored in every k-iteration, dramatically
         * reducing memory traffic to C. */
        Ci[j] = Ci[j] * beta_local + alpha_local * sum;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
