    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* --------------------------------------------------------------------
   * Optimization overview
   *
   * Original kernel structure:
   *   for i
   *     for j <= i           // scale C by beta
   *       C[i][j] *= beta
   *     for k
   *       for j <= i         // syr2k update
   *         C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
   *
   * Issues:
   *   - A[j][k] and B[j][k] are accessed with j as the innermost index.
   *     In row-major layout this is a column-wise, strided access, which
   *     is cache-unfriendly and hard to vectorize.
   *   - The factors alpha, A[i][k], B[i][k] are redundantly multiplied
   *     inside the innermost loop.
   *
   * Key ideas:
   *   1. Build explicit transposes At and Bt so that column accesses of
   *      A and B become contiguous in memory:
   *        At[k*n + i] == A[i][k]
   *        Bt[k*n + i] == B[i][k]
   *   2. Reorder loops to
   *        for k
   *          for i
   *            for j <= i
   *      and factor common terms:
   *        aik_alpha = alpha * A[i][k]
   *        bik_alpha = alpha * B[i][k]
   *        C[i][j] += A[j][k] * bik_alpha + B[j][k] * aik_alpha
   *
   * This preserves the per-element floating-point operation sequence:
   *   - Each C[i][j] is scaled by beta exactly once, before any updates.
   *   - The sum over k is still accumulated in strictly increasing k.
   * -------------------------------------------------------------------- */

  /* Allocate transposed views of A and B.
   *
   * Layout:
   *   At and Bt are of size m x n, stored in row-major order:
   *     At[k*n + i] = A[i][k]
   *     Bt[k*n + i] = B[i][k]
   *
   * This turns column accesses A[j][k], B[j][k] (varying j, fixed k)
   * into dense, unit-stride walks over At and Bt.
   *
   * The O(n*m) cost of this transpose is negligible compared to the
   * O(n^2*m) cost of the syr2k update itself and is fully timed.
   */
  const unsigned long long nm = (unsigned long long)n * (unsigned long long)m;
  DATA_TYPE *restrict At =
      (DATA_TYPE*)polybench_alloc_data(nm, sizeof(DATA_TYPE));
  DATA_TYPE *restrict Bt =
      (DATA_TYPE*)polybench_alloc_data(nm, sizeof(DATA_TYPE));

  /* Build transposes: At[k*n + i] = A[i][k], Bt[k*n + i] = B[i][k]. */
  for (i = 0; i < n; ++i)
  {
    for (k = 0; k < m; ++k)
    {
      const unsigned long long idx = (unsigned long long)k * (unsigned long long)n
                                   + (unsigned long long)i;
      At[idx] = A[i][k];
      Bt[idx] = B[i][k];
    }
  }

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* 1. Scale the lower-triangular part of C by beta. */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *restrict Ci = &C[i][0];
    for (j = 0; j <= i; j++)
    {
      Ci[j] *= beta;
    }
  }

  /* 2. Rank-2k symmetric update using transposed A and B. */
  for (k = 0; k < _PB_M; k++)
  {
    /* Pointers to the k-th "column" of A and B, stored contiguously. */
    const DATA_TYPE *restrict Acol =
        At + (unsigned long long)k * (unsigned long long)n;
    const DATA_TYPE *restrict Bcol =
        Bt + (unsigned long long)k * (unsigned long long)n;

    for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict Ci = &C[i][0];

      /* Precompute factors that are constant over j for this (i, k). */
      const DATA_TYPE aik_alpha = alpha * Acol[i]; /* alpha * A[i][k] */
      const DATA_TYPE bik_alpha = alpha * Bcol[i]; /* alpha * B[i][k] */

      const int max_j = i; /* lower-triangular: 0 <= j <= i */

      /* Inner loop: unit-stride over C[i][*], Acol[*], Bcol[*]. */
      for (j = 0; j <= max_j; j++)
      {
        Ci[j] += Acol[j] * bik_alpha + Bcol[j] * aik_alpha;
      }
    }
  }
#pragma endscop

  /* Free temporary transposed buffers. */
  free(At);
  free(Bt);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
