#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"

/* Tunable blocking factors for the main kernel.
   They can be overridden at compile time, e.g. with:
     -DSYR2K_J_BLOCK=64 -DSYR2K_K_BLOCK=256 */
#ifndef SYR2K_J_BLOCK
#define SYR2K_J_BLOCK 32
#endif

#ifndef SYR2K_K_BLOCK
#define SYR2K_K_BLOCK 256
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* Use local restrict pointers to help the compiler and improve
     alias analysis.  The dimensions use the runtime sizes (n, m). */
  DATA_TYPE (*restrict C_)[n] = (DATA_TYPE (*restrict)[n])C;
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*restrict)[m])A;
  DATA_TYPE (*restrict B_)[m] = (DATA_TYPE (*restrict)[m])B;

  /* Hoist loop-invariant divisions out of the loops. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;
  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;

  /* Initialize A and B: traverse rows (j is the innermost index),
     which is contiguous in memory for row-major layout. */
  for (i = 0; i < n; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE *restrict Bi = B_[i];

    for (j = 0; j < m; j++)
    {
      int ij = i * j;
      Ai[j] = (DATA_TYPE)((ij + 1) % n) * inv_n;
      Bi[j] = (DATA_TYPE)((ij + 2) % m) * inv_m;
    }
  }

  /* Initialize C: again, access rows contiguously. */
  for (i = 0; i < n; i++)
  {
    DATA_TYPE *restrict Ci = C_[i];

    for (j = 0; j < n; j++)
    {
      Ci[j] = (DATA_TYPE)((i * j + 3) % n) * inv_m;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Use local restrict-qualified VLA pointers for C, A, and B to
     improve alias analysis.
   - Reorder loops to make the innermost loop iterate over the
     contiguous (second) dimension of A and B, improving spatial
     locality and enabling efficient vectorization.
   - Fuse the beta scaling of C into the main computation so each
     C[i][j] element is loaded and stored only once.
   - Add simple blocking over j and k with tunable block sizes
     (SYR2K_J_BLOCK, SYR2K_K_BLOCK) to keep working sets cache-friendly
     for large problem sizes.
   - Preserve, for each element C[i][j], the order of arithmetic
     operations with respect to the original kernel. */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Local restrict-qualified pointers to the 2D arrays.
     Using the runtime sizes (n, m) keeps the code correct for all
     PolyBench datasets while giving the optimizer precise shapes. */
  DATA_TYPE (*restrict C_)[n] = (DATA_TYPE (*restrict)[n])C;
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*restrict)[m])A;
  DATA_TYPE (*restrict B_)[m] = (DATA_TYPE (*restrict)[m])B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ci             = C_[i];
    const DATA_TYPE *restrict Ai_row   = A_[i];
    const DATA_TYPE *restrict Bi_row   = B_[i];

    /* Process the lower-triangular part of row i in blocks of columns j. */
    for (int j_block = 0; j_block <= i; j_block += SYR2K_J_BLOCK) {
      int j_max = j_block + SYR2K_J_BLOCK - 1;
      if (j_max > i)
        j_max = i;

      for (j = j_block; j <= j_max; j++) {
        const DATA_TYPE *restrict Aj_row = A_[j];
        const DATA_TYPE *restrict Bj_row = B_[j];

        /* Start from beta * C[i][j] (beta scaling fused into the update). */
        DATA_TYPE cij = Ci[j] * beta_local;

        /* Tile the reduction over k so that, for large M, the working
           set in the innermost loop fits better in the cache.  The k
           loop still walks the contiguous dimension with unit stride. */
        for (int k_block = 0; k_block < _PB_M; k_block += SYR2K_K_BLOCK) {
          int k_max = k_block + SYR2K_K_BLOCK;
          if (k_max > _PB_M)
            k_max = _PB_M;

#pragma GCC ivdep
          for (k = k_block; k < k_max; k++) {
            const DATA_TYPE a_ik = Ai_row[k];
            const DATA_TYPE b_ik = Bi_row[k];
            const DATA_TYPE a_jk = Aj_row[k];
            const DATA_TYPE b_jk = Bj_row[k];

            /* Same arithmetic as the original kernel:
                 C[i][j] += alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k]);
               performed in the same k order for each (i,j). */
            cij += alpha_local * (a_jk * b_ik + b_jk * a_ik);
          }
        }

        Ci[j] = cij;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
