/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   - Access A and B in a row-contiguous manner (k is innermost).
   - Keep each C(i,j) value in a register for the full inner
     accumulation instead of repeatedly loading/storing it.
   - Introduce local restrict-qualified pointers to help the
     compiler with alias analysis and vectorization.
   - Manually unroll the k loop by SYR2K_K_UNROLL (default: 4).

   Semantics note:
   For each (i,j) pair, the accumulation over k is still performed
   in strictly increasing k order, and the beta scaling is applied
   once before the accumulation begins. This preserves the original
   floating-point evaluation order for every C[i][j] element. Only
   the ordering of operations between different C[i][j] elements is
   changed, which is allowed because they are independent.
*/
static
void kernel_syr2k [[gnu::flatten, gnu::noinline]] (int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Local aliases with explicit restrict-qualified VLA pointers.
     This gives the compiler stronger information for optimization
     while preserving the original data layout. */
  DATA_TYPE (*restrict C_)[n] = (DATA_TYPE (*restrict)[n]) C;
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*restrict)[m]) A;
  DATA_TYPE (*restrict B_)[m] = (DATA_TYPE (*restrict)[m]) B;

  const int nPB = _PB_N;
  const int mPB = _PB_M;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Outer loop over rows of C (and A/B). */
  for (i = 0; i < nPB; i++)
  {
    /* Pointers to the current row i of each matrix. */
    DATA_TYPE *restrict Ci = C_[i];
    DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE *restrict Bi = B_[i];

    /* Only the lower triangle (j <= i) is updated (uplo = 'L'). */
    for (j = 0; j <= i; j++)
    {
      /* Pointers to row j of A and B. */
      DATA_TYPE *restrict Aj = A_[j];
      DATA_TYPE *restrict Bj = B_[j];

      /* Load C(i,j), apply beta scaling once, then accumulate the
         rank-2k update into this register-resident scalar. */
      DATA_TYPE cij = Ci[j] * beta_local;

      /* Manually unrolled inner-product over k. We preserve the
         original evaluation order over k for this element. */
      int k_limit = mPB - (mPB % SYR2K_K_UNROLL);
      for (k = 0; k < k_limit; k += SYR2K_K_UNROLL)
      {
        /* Unroll factor 1 */
        cij += alpha_local * (Aj[k] * Bi[k] + Bj[k] * Ai[k]);

#if SYR2K_K_UNROLL > 1
        /* Unroll factor 2 */
        cij += alpha_local * (Aj[k+1] * Bi[k+1] + Bj[k+1] * Ai[k+1]);
#endif

#if SYR2K_K_UNROLL > 2
        /* Unroll factor 3 */
        cij += alpha_local * (Aj[k+2] * Bi[k+2] + Bj[k+2] * Ai[k+2]);
#endif

#if SYR2K_K_UNROLL > 3
        /* Unroll factor 4 */
        cij += alpha_local * (Aj[k+3] * Bi[k+3] + Bj[k+3] * Ai[k+3]);
#endif

        /* If SYR2K_K_UNROLL is set higher than 4, extend this
           pattern accordingly. */
      }

      /* Handle any remaining k values (tail of the row). */
      for (; k < mPB; ++k)
      {
        cij += alpha_local * (Aj[k] * Bi[k] + Bj[k] * Ai[k]);
      }

      /* Store the fully accumulated value back to C. */
      Ci[j] = cij;
    }
  }
#pragma endscop
}


